UPDATE account
SET balance = balance + CASE
  WHEN id = #{depositAccountId} THEN #{amount}
  WHEN id = #{withdrawalAccountId} THEN -#{amount}
END
WHERE id IN (#{depositAccountId}, #{withdrawalAccountId})
  AND status = 'ACTIVE'
  AND (
    id = #{depositAccountId}
    OR balance >= #{amount}
  )
